mapper.select:
select s.*, p.name as providerName, p.avatar as providerAvatar, p.score as providerScore from slot s inner join provider p on s.provider_id = p.id where s.status = 1 and p.status = 1
and s.service_id = #{serviceId}
and s.service_date = #{serviceDate}
and s.provider_id = #{providerId}
order by s.start_time, p.score desc

select s.*,
       p.name   as providerName,
       p.avatar as providerAvatar,
       p.score  as providerScore
from slot s
left join provider p on s.provider_id = p.id


        and s.service_id = #{serviceId}


        and s.service_date = #{serviceDate}


        and s.provider_id = #{providerId}


order by s.service_date desc, s.start_time
